package net.resheim.timekeeper.server;

import static net.resheim.timekeeper.server.JsonValues.*;
import static org.junit.jupiter.api.Assertions.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.function.Supplier;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.quarkus.test.junit.*;
import jakarta.inject.Inject;
import net.resheim.eclipse.timekeeper.domain.*;
import net.resheim.eclipse.timekeeper.service.Commands.*;
import org.junit.jupiter.api.Test;

@QuarkusTest @TestProfile(TaskProviderIdentitiesTest.Profile.class)
class TaskProviderIdentitiesTest {
    public static class Profile implements QuarkusTestProfile {public Map<String,String> getConfigOverrides(){var config=TaskProviderTestDatabase.settings("task_provider_identities");config.put("timekeeper.tasks.automatic","false");return config;}}
    @Inject ServerStore store;@Inject CommandReceipts receipts;@Inject ContractInputs inputs;
    record Fixture(String owner,UUID connection,UUID oldList,UUID newList,UUID oldProject,UUID newProject,UUID task){}
    private TaskProviderConnections connections(){return new TaskProviderConnections(store);}
    private TaskProviderScans scans(){return new TaskProviderScans(store,receipts,inputs);}
    private TaskProviderIdentities identities(){return new TaskProviderIdentities(store,receipts,inputs);}
    private <T>T tx(Fixture f,Supplier<T> work){return store.transaction(f.owner(),work);}
    private TaskCloudProvider.RemoteTask remote(String id,String title){var raw=object().put("id",id).put("title",title).put("status","needsAction").put("position","001").put("etag","\"g-"+id+"\"").put("webViewLink","https://tasks.google.com/"+id);raw.putArray("links").add(object().put("type","generic").put("description","Source "+id).put("link","https://example.invalid/source/"+id));return new TaskCloudProvider(TaskCloudProvider.Provider.GOOGLE).normalize(raw);}
    private TaskProviderConnections.Claim claim(Fixture f,int index){return tx(f,()->{var auth=connections().required(f.connection());auth.put("roundActive",true).put("roundIndex",index).putNull("lease").putNull("leaseUntil").put("nextRefresh",store.now().toString());connections().save(TaskProviderConnections.AUTH,auth);return connections().claim(f.connection(),false);});}
    private ObjectNode stage(Fixture f,int index,TaskCloudProvider.RemoteTask...items){var claim=claim(f,index);return tx(f,()->{var start=scans().begin(claim);var ready=scans().acknowledge(claim,start,new TaskCloudProvider.Page<>(List.of(items),null,null));scans().reconcile(claim);return ready;});}
    private void approve(Fixture f,UUID list){var review=tx(f,()->scans().review(f.connection(),list));tx(f,()->scans().approve(f.connection(),list,etag(review)));}
    private Fixture fixture(){return fixture(true);}
    private Fixture fixture(boolean approveNew){
        String owner="identity-owner-"+UUID.randomUUID();var f=store.transaction(owner,()->{
            var settings=new TaskProviderOAuth.Settings("client","synthetic-secret","https://example.invalid/web/task-provider-callback.html");var attempt=connections().begin(TaskCloudProvider.Provider.GOOGLE,settings,"browser");String state=Arrays.stream(URI.create(attempt.path("authorizationUrl").asText()).getRawQuery().split("&")).filter(value->value.startsWith("state=")).map(value->URLDecoder.decode(value.substring(6),StandardCharsets.UTF_8)).findFirst().orElseThrow();
            var connection=connections().connect(connections().consume(state,"browser"),settings,new TaskCloudProvider.Account("account","Google"),new TaskProviderOAuth.Tokens("synthetic-access","synthetic-refresh",store.now().plusSeconds(3600),Set.of("openid","https://www.googleapis.com/auth/tasks.readonly")),List.of(new TaskCloudProvider.RemoteList("old","Old","STANDARD",false,true,object().put("id","old").put("title","Old")),new TaskCloudProvider.RemoteList("new","New","STANDARD",false,true,object().put("id","new").put("title","New"))));
            var oldProject=store.service().createProject(new CreateProject("Original project"));var newProject=store.service().createProject(new CreateProject("New imports project"));UUID id=uuid(connection.get("id"));connections().select(id,List.of("old","new"),object().put("old",oldProject.id().value().toString()).put("new",newProject.id().value().toString()),etag(connection));var lists=store.list("TASK_LIST");UUID old=uuid(lists.stream().filter(list->list.path("remoteListId").asText().equals("old")).findFirst().orElseThrow().get("id")),next=uuid(lists.stream().filter(list->list.path("remoteListId").asText().equals("new")).findFirst().orElseThrow().get("id"));return new Fixture(owner,id,old,next,oldProject.id().value(),newProject.id().value(),null);
        });
        stage(f,0,remote("old-id","Original provider title"));approve(f,f.oldList());if(approveNew){stage(f,1);approve(f,f.newList());}UUID task=tx(f,()->uuid(store.list("TASK").getFirst().get("id")));return new Fixture(owner,f.connection(),f.oldList(),f.newList(),f.oldProject(),f.newProject(),task);
    }
    private JsonNode task(Fixture f){return tx(f,()->store.find("TASK",f.task()).orElseThrow());}
    private JsonNode review(Fixture f,UUID list){var page=tx(f,()->identities().list(f.connection(),list,null));inputs.validate("TaskProviderIdentityReviews",page);assertEquals(1,page.path("count").asInt());return page.path("items").get(0);}
    private ObjectNode replace(Fixture f,JsonNode current,String repository,String id,String target){return object().put("externalId",target).put("decision","REPLACE").put("taskId",current.path("id").asText()).put("taskEtag",etag(current)).set("previous",object().put("providerId","google").put("repositoryId",repository).put("externalId",id));}
    @Test void additionsWaitForOwnedReviewAndExplicitImportKeepsTheListMappingAndReceipt(){
        var f=fixture();stage(f,1,remote("new-id","New task"));assertEquals(1,tx(f,()->store.list("TASK").size()));var row=review(f,f.newList());assertTrue(row.path("canImport").asBoolean());assertTrue(row.path("canReplace").asBoolean());var input=object().put("decision","IMPORT").put("externalId","new-id");inputs.validate("TaskProviderIdentityDecisionInput",input);
        assertEquals(412,assertThrows(ApiFailure.class,()->tx(f,()->identities().decide(f.connection(),f.newList(),"\"stale\"",input))).status);var result=tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),input));assertEquals(f.newProject().toString(),result.body().path("projectId").asText());assertEquals(f.oldProject().toString(),task(f).path("projectId").asText());assertEquals(2,tx(f,()->store.list("TASK").size()));assertEquals(result.body().toString(),tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),input)).body().toString());assertEquals(2,tx(f,()->store.list("TASK").size()));
    }
    @Test void replacingAMovedIdentityPreservesNativeFieldsResourcesAndAliasesAndRetiredDeletionCannotDeleteIt(){
        var f=fixture();String local=UUID.randomUUID().toString();tx(f,()->{var current=((ObjectNode)store.find("TASK",f.task()).orElseThrow()).deepCopy();current.put("summary","My native title").put("url","https://example.invalid/own-url").put("priority","HIGH");current.set("body",object().put("format","HTML").put("content","<p>Keep <b>rich</b> notes</p>"));current.withObject("metadata").withArray("links").add(object().put("id",local).put("kind","LOCAL").put("url","https://example.invalid/local").putNull("title").putNull("providerId").putNull("remoteId"));current.put("version",current.path("version").asLong()+1);store.save("TASK",(Task)decode("TASK",current));return null;});
        var before=task(f);stage(f,1,remote("changed-id","Changed at provider"));var row=review(f,f.newList());var input=replace(f,before,TaskCloudPull.repository("account","old"),"old-id","changed-id");inputs.validate("TaskProviderIdentityDecisionInput",input);var result=tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),input));var after=result.body();
        for(String field:List.of("id","projectId","parentTaskId","summary","url","priority","body","status","completedAt","reminders","recurrence"))assertEquals(before.path(field),after.path(field),field);assertEquals(f.newList().toString(),after.path("externalReferences").get(0).path("taskListId").asText());assertEquals("changed-id",after.path("externalReferences").get(0).path("externalId").asText());assertTrue(after.path("externalReferences").get(0).path("providerData").path("payload").path("policy").path("localHierarchy").asBoolean());assertEquals(2,after.path("metadata").path("links").size());assertTrue(after.path("metadata").path("links").toString().contains(local));assertTrue(after.path("metadata").path("links").toString().contains("source/changed-id"));assertFalse(after.path("metadata").path("links").toString().contains("source/old-id"));
        assertEquals(f.task().toString(),tx(f,()->store.byReference(new ExternalTaskReferenceKey("google",TaskCloudPull.repository("account","old"),"old-id")).orElseThrow()).path("id").asText());var current=task(f);var deleted=new TaskCloudProvider(TaskCloudProvider.Provider.GOOGLE).normalize(object().put("id","old-id").put("deleted",true));stage(f,0,deleted);assertEquals(current,task(f));assertTrue(tx(f,()->store.list("TASK_TOMBSTONE").isEmpty()));assertEquals(1,tx(f,()->store.list("TASK").size()));
    }
    @Test void aRetiredIdentityCanBeExplicitlyRestoredWithoutCreatingADuplicate(){
        var f=fixture();stage(f,1,remote("changed-id","Moved"));var row=review(f,f.newList());var first=task(f);tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),replace(f,first,TaskCloudPull.repository("account","old"),"old-id","changed-id")));
        stage(f,0,remote("old-id","Returned"));var back=review(f,f.oldList());assertEquals(f.task().toString(),back.path("taskId").asText());assertFalse(back.path("canImport").asBoolean());var current=task(f);tx(f,()->identities().decide(f.connection(),f.oldList(),back.path("reviewEtag").asText(),replace(f,current,TaskCloudPull.repository("account","new"),"changed-id","old-id")));assertEquals("old-id",task(f).path("externalReferences").get(0).path("externalId").asText());assertEquals(1,tx(f,()->store.list("TASK").size()));
    }
    @Test void changedNativeTasksAndOtherOwnersCannotUseACapturedIdentityChoice(){
        var f=fixture();stage(f,1,remote("new-id","New"));var row=review(f,f.newList());var before=task(f);var input=replace(f,before,TaskCloudPull.repository("account","old"),"old-id","new-id");assertThrows(ApiFailure.class,()->store.transaction("other-"+UUID.randomUUID(),()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),input)));
        tx(f,()->{var value=(Task)decode("TASK",store.find("TASK",f.task()).orElseThrow());store.service().updateTask(new UpdateTask(value.id(),value.version(),value.projectId(),value.parentTaskId(),"New local edit",value.url()));return null;});assertEquals(412,assertThrows(ApiFailure.class,()->tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),input))).status);assertEquals("New local edit",task(f).path("summary").asText());assertEquals(1,tx(f,()->store.list("TASK").size()));
    }
    @Test void identityReplacementAcceptsIndependentProviderEditsAndAutomaticAdditionsRemainAnExplicitOption(){
        var f=fixture();stage(f,1,remote("changed-id","Independent Google title"));var row=review(f,f.newList());var before=task(f);tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),replace(f,before,TaskCloudPull.repository("account","old"),"old-id","changed-id")));assertEquals("Independent Google title",task(f).path("summary").asText());assertEquals(f.oldProject().toString(),task(f).path("projectId").asText());
        tx(f,()->{var auth=connections().view(f.connection());connections().select(f.connection(),List.of("old","new"),null,etag(auth),false);return null;});stage(f,1,remote("second-new-id","Automatic addition"));assertEquals(2,tx(f,()->store.list("TASK").size()));assertFalse(tx(f,()->connections().view(f.connection())).path("reviewAdditions").asBoolean());
    }

    @Test void editedSourceResourcesAreNotDiscardedWhenTheIdentityChanges(){
        var f=fixture();String oldResource=task(f).path("metadata").path("links").get(0).path("id").asText();tx(f,()->{var current=((ObjectNode)store.find("TASK",f.task()).orElseThrow()).deepCopy();((ObjectNode)current.path("metadata").path("links").get(0)).put("title","Locally annotated source");current.put("version",current.path("version").asLong()+1);store.save("TASK",(Task)decode("TASK",current));return null;});stage(f,1,remote("changed-id","Moved"));var row=review(f,f.newList());var before=task(f);tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),replace(f,before,TaskCloudPull.repository("account","old"),"old-id","changed-id")));var after=task(f);assertEquals(2,after.path("metadata").path("links").size());assertTrue(after.path("metadata").path("links").toString().contains(oldResource));assertTrue(after.path("metadata").path("links").toString().contains("Locally annotated source"));
    }
    @Test void replacementCannotUseAnotherProviderAccountOrAnExpiredScan(){
        var f=fixture();stage(f,1,remote("new-id","New"));var row=review(f,f.newList());UUID other=UUID.randomUUID(),list=UUID.randomUUID(),task=UUID.randomUUID();
        tx(f,()->{var conn=((ObjectNode)store.find("TASK_CONNECTION",f.connection()).orElseThrow()).deepCopy();conn.put("id",other.toString()).put("remoteAccountId","other-account").put("version",0);store.save("TASK_CONNECTION",decode("TASK_CONNECTION",conn));var sourceList=((ObjectNode)store.find("TASK_LIST",f.oldList()).orElseThrow()).deepCopy();sourceList.put("id",list.toString()).put("connectionId",other.toString()).put("version",0);store.save("TASK_LIST",decode("TASK_LIST",sourceList));var copy=((ObjectNode)store.find("TASK",f.task()).orElseThrow()).deepCopy();copy.put("id",task.toString()).put("version",0);var ref=(ObjectNode)copy.path("externalReferences").get(0);ref.put("repositoryId",TaskCloudPull.repository("other-account","old")).put("taskListId",list.toString());store.save("TASK",decode("TASK",copy));return null;});
        var otherTask=tx(f,()->store.find("TASK",task).orElseThrow());var input=replace(f,otherTask,TaskCloudPull.repository("other-account","old"),"old-id","new-id");assertEquals(409,assertThrows(ApiFailure.class,()->tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),input))).status);assertEquals(otherTask,tx(f,()->store.find("TASK",task).orElseThrow()));
        tx(f,()->{var scan=((ObjectNode)store.find(TaskProviderScans.SCAN,f.newList()).orElseThrow()).deepCopy();scan.put("startedAt",store.now().minusSeconds(901).toString());connections().save(TaskProviderScans.SCAN,scan);return null;});assertEquals(409,assertThrows(ApiFailure.class,()->tx(f,()->identities().list(f.connection(),f.newList(),null))).status);assertEquals(2,tx(f,()->store.list("TASK").size()));
    }

    @Test void explicitlyRetiringAnUnavailableOldLinkDoesNotModifyItsUnselectedList(){
        var f=fixture();tx(f,()->{var auth=connections().view(f.connection());connections().select(f.connection(),List.of("new"),null,etag(auth));var old=((ObjectNode)store.find("TASK_LIST",f.oldList()).orElseThrow()).deepCopy();old.put("present",false).put("readable",false).put("version",old.path("version").asLong()+1);store.save("TASK_LIST",decode("TASK_LIST",old));return null;});var old=tx(f,()->store.find("TASK_LIST",f.oldList()).orElseThrow());stage(f,0,remote("changed-id","Moved"));var row=review(f,f.newList());var before=task(f);tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),replace(f,before,TaskCloudPull.repository("account","old"),"old-id","changed-id")));assertEquals(old,tx(f,()->store.find("TASK_LIST",f.oldList()).orElseThrow()));assertEquals(f.oldProject().toString(),task(f).path("projectId").asText());assertEquals("changed-id",task(f).path("externalReferences").get(0).path("externalId").asText());
    }

    @Test void reviewingOneIdentityBeforeFirstApprovalDoesNotImportTheOtherRecords(){
        var f=fixture(false);stage(f,1,remote("first-new","First"),remote("second-new","Second"));var page=tx(f,()->identities().list(f.connection(),f.newList(),null));assertEquals(2,page.path("count").asInt());var row=page.path("items").get(0);var input=object().put("decision","IMPORT").put("externalId",row.path("externalId").asText());tx(f,()->identities().decide(f.connection(),f.newList(),row.path("reviewEtag").asText(),input));assertEquals(2,tx(f,()->store.list("TASK").size()));assertEquals(1,tx(f,()->scans().review(f.connection(),f.newList())).path("createCount").asInt());approve(f,f.newList());assertEquals(3,tx(f,()->store.list("TASK").size()));
    }

}
